UPDATE  sys_user_integral_record  set status =1,updatedt=#{updateTime}  where orderId =#{outTradeNo};
UPDATE sys_user_integral set integralvalue=(select   integralvalue from  sys_user_integral_record where  status =1 and orderId=#{outTradeNo} order by createdt desc limit  1)
where studenterid =(SELECT studenterid FROM sys_user_integral_record WHERE orderId=#{outTradeNo} AND status=1 order by createdt desc limit  1)

